import { workerMcpEnv, type WorkerConfig } from './config.js'

/**
 * Copy of the runner's redaction rules (scrum4me-docker `lib/log-redact.ts:9-58`, 52ded13).
 * ...
 */
export const REDACTED = '***'

const SECRET_NAME = /(TOKEN|SECRET|PASSWORD|PASSWD|API_KEY|PRIVATE_KEY|_KEY$|DSN|CREDENTIAL)/i

/** The password part of a URL value, raw (as written) if present. */
function rawUrlPassword(value: string): string | undefined {
  const m = value.match(/:\/\/[^/@]*:([^@]*)@/)
  return m ? m[1] : undefined
}

export function collectSecretEntries(...envs: Array<Record<string, string | undefined>>): { name: string; value: string }[] {
  const entries: { name: string; value: string }[] = []
  const seen = new Set<string>()
  const add = (name: string, value: string) => {
    if (!value) return
    if (seen.has(value)) return
    seen.add(value)
    entries.push({ name, value })
  }
  for (const env of envs) {
    for (const [name, value] of Object.entries(env)) {
      if (!value) continue
      if (SECRET_NAME.test(name)) add(name, value)
      // The password inside every URL value, raw and decoded.
      const raw = rawUrlPassword(value)
      if (raw !== undefined) add(`${name} (url-wachtwoord)`, raw)
      try {
        const decoded = new URL(value).password
        if (decoded) add(`${name} (url-wachtwoord)`, decoded)
      } catch {
        // Not a URL.
      }
    }
  }
  return entries
}
```

